"""
Base Strategy Abstract Class
All trading strategies should inherit from this class
"""

import asyncio
import logging
from abc import ABC, abstractmethod
from typing import Dict, Any, Optional, List
from dataclasses import dataclass
from datetime import datetime

@dataclass
class TradeSignal:
    """Represents a trading signal generated by a strategy"""
    action: str  # 'buy' or 'sell'
    token_address: str
    amount: float
    price: Optional[float] = None
    confidence: float = 1.0  # 0.0 to 1.0
    reason: str = ""
    timestamp: datetime = None
    metadata: Dict[str, Any] = None

    def __post_init__(self):
        if self.timestamp is None:
            self.timestamp = datetime.utcnow()
        if self.metadata is None:
            self.metadata = {}

@dataclass
class Position:
    """Represents a trading position"""
    token_address: str
    amount: float
    entry_price: float
    entry_time: datetime
    current_price: Optional[float] = None
    unrealized_pnl: Optional[float] = None
    take_profit: Optional[float] = None
    stop_loss: Optional[float] = None
    status: str = "open"  # open, closed, partial

class BaseStrategy(ABC):
    """
    Abstract base class for all trading strategies
    """
    
    def __init__(self, bot, name: str = None, config: Dict[str, Any] = None):
        """
        Initialize the strategy
        
        Args:
            bot: Reference to the main trading bot
            name: Strategy name
            config: Strategy-specific configuration
        """
        self.bot = bot
        self.name = name or self.__class__.__name__
        self.config = config or {}
        self.logger = logging.getLogger(f"Strategy.{self.name}")
        
        # Strategy state
        self.is_running = False
        self.is_paused = False
        self.positions: Dict[str, Position] = {}
        self.signals: List[TradeSignal] = []
        
        # Performance tracking
        self.total_trades = 0
        self.winning_trades = 0
        self.total_pnl = 0.0
        self.start_time = None
        
    async def start(self):
        """Start the strategy"""
        if self.is_running:
            self.logger.warning(f"Strategy {self.name} is already running")
            return
            
        self.logger.info(f"Starting strategy: {self.name}")
        self.is_running = True
        self.is_paused = False
        self.start_time = datetime.utcnow()
        
        try:
            await self.initialize()
            await self._run_loop()
        except Exception as e:
            self.logger.error(f"Error in strategy {self.name}: {e}")
            await self.stop()
            raise
    
    async def stop(self):
        """Stop the strategy"""
        self.logger.info(f"Stopping strategy: {self.name}")
        self.is_running = False
        await self.cleanup()
        
    async def pause(self):
        """Pause the strategy"""
        self.logger.info(f"Pausing strategy: {self.name}")
        self.is_paused = True
        
    async def resume(self):
        """Resume the strategy"""
        self.logger.info(f"Resuming strategy: {self.name}")
        self.is_paused = False
    
    async def _run_loop(self):
        """Main strategy execution loop"""
        while self.is_running:
            try:
                if not self.is_paused:
                    await self.execute()
                await asyncio.sleep(self.config.get('execution_interval', 1.0))
            except Exception as e:
                self.logger.error(f"Error in strategy execution: {e}")
                if not self.config.get('continue_on_error', True):
                    break
                await asyncio.sleep(5)  # Wait before retrying
    
    @abstractmethod
    async def initialize(self):
        """
        Initialize the strategy (abstract method)
        Called when the strategy starts
        """
        pass
    
    @abstractmethod
    async def execute(self):
        """
        Main strategy logic (abstract method)
        Called repeatedly while the strategy is running
        """
        pass
    
    @abstractmethod
    async def cleanup(self):
        """
        Cleanup resources (abstract method)
        Called when the strategy stops
        """
        pass
    
    async def on_new_token(self, token_data: Dict[str, Any]):
        """
        Handle new token events
        Override in subclasses if needed
        """
        pass
    
    async def on_price_update(self, token_address: str, price_data: Dict[str, Any]):
        """
        Handle price update events
        Override in subclasses if needed
        """
        pass
    
    async def on_wallet_transaction(self, wallet_address: str, transaction_data: Dict[str, Any]):
        """
        Handle wallet transaction events
        Override in subclasses if needed
        """
        pass
    
    def generate_signal(self, action: str, token_address: str, amount: float, 
                       confidence: float = 1.0, reason: str = "", **kwargs) -> TradeSignal:
        """
        Generate a trading signal
        
        Args:
            action: 'buy' or 'sell'
            token_address: Token contract address
            amount: Amount to trade
            confidence: Signal confidence (0.0 to 1.0)
            reason: Reason for the signal
            **kwargs: Additional metadata
        """
        signal = TradeSignal(
            action=action,
            token_address=token_address,
            amount=amount,
            confidence=confidence,
            reason=reason,
            metadata=kwargs
        )
        
        self.signals.append(signal)
        self.logger.info(f"Generated {action} signal for {token_address}: {reason}")
        
        return signal
    
    async def execute_signal(self, signal: TradeSignal) -> bool:
        """
        Execute a trading signal through the bot
        
        Args:
            signal: TradeSignal to execute
            
        Returns:
            bool: True if execution was successful
        """
        try:
            # Delegate to the bot's trading engine
            success = await self.bot.execute_trade(signal)
            
            if success:
                self.total_trades += 1
                self.logger.info(f"Successfully executed {signal.action} for {signal.token_address}")
            else:
                self.logger.error(f"Failed to execute {signal.action} for {signal.token_address}")
                
            return success
            
        except Exception as e:
            self.logger.error(f"Error executing signal: {e}")
            return False
    
    def add_position(self, position: Position):
        """Add a new position to tracking"""
        self.positions[position.token_address] = position
        self.logger.info(f"Added position for {position.token_address}: {position.amount}")
    
    def close_position(self, token_address: str, exit_price: float, reason: str = ""):
        """Close a position and calculate PnL"""
        if token_address not in self.positions:
            self.logger.warning(f"No position found for {token_address}")
            return
            
        position = self.positions[token_address]
        position.status = "closed"
        position.current_price = exit_price
        
        # Calculate PnL
        pnl = (exit_price - position.entry_price) * position.amount
        position.unrealized_pnl = pnl
        self.total_pnl += pnl
        
        if pnl > 0:
            self.winning_trades += 1
            
        self.logger.info(f"Closed position for {token_address}: PnL = {pnl:.4f} SOL, Reason: {reason}")
        
        # Move to historical positions or remove
        del self.positions[token_address]
    
    def get_performance_stats(self) -> Dict[str, Any]:
        """Get strategy performance statistics"""
        win_rate = (self.winning_trades / self.total_trades * 100) if self.total_trades > 0 else 0
        
        runtime = (datetime.utcnow() - self.start_time).total_seconds() if self.start_time else 0
        
        return {
            "name": self.name,
            "total_trades": self.total_trades,
            "winning_trades": self.winning_trades,
            "win_rate": win_rate,
            "total_pnl": self.total_pnl,
            "runtime_seconds": runtime,
            "active_positions": len(self.positions),
            "is_running": self.is_running,
            "is_paused": self.is_paused
        }
        
    def should_take_profit(self, position: Position, current_price: float) -> bool:
        """Check if position should take profit"""
        if not position.take_profit:
            return False
            
        profit_percentage = ((current_price - position.entry_price) / position.entry_price) * 100
        return profit_percentage >= position.take_profit
    
    def should_stop_loss(self, position: Position, current_price: float) -> bool:
        """Check if position should stop loss"""
        if not position.stop_loss:
            return False
            
        loss_percentage = ((position.entry_price - current_price) / position.entry_price) * 100
        return loss_percentage >= position.stop_loss
        
    def update_position_price(self, token_address: str, current_price: float):
        """Update position with current price"""
        if token_address in self.positions:
            position = self.positions[token_address]
            position.current_price = current_price
            position.unrealized_pnl = (current_price - position.entry_price) * position.amount
            
            # Check for auto-close conditions
            if self.should_take_profit(position, current_price):
                asyncio.create_task(self._auto_close_position(token_address, current_price, "take_profit"))
            elif self.should_stop_loss(position, current_price):
                asyncio.create_task(self._auto_close_position(token_address, current_price, "stop_loss"))
    
    async def _auto_close_position(self, token_address: str, price: float, reason: str):
        """Automatically close a position"""
        try:
            # Generate sell signal
            position = self.positions.get(token_address)
            if not position:
                return
                
            signal = self.generate_signal(
                action="sell",
                token_address=token_address,
                amount=position.amount,
                confidence=1.0,
                reason=f"Auto-close: {reason}",
                auto_close=True
            )
            
            # Execute the sell
            success = await self.execute_signal(signal)
            if success:
                self.close_position(token_address, price, reason)
                
        except Exception as e:
            self.logger.error(f"Error auto-closing position {token_address}: {e}")
